import org.openenglish.reader.*;import android.content.Context;import java.io.*;import java.nio.file.*;import org.json.*;
public final class IslandContinuationTest {
 static int checks;static void check(boolean v,String s){if(!v)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}
 public static void main(String[] args)throws Exception{
  File root=Files.createTempDirectory("scene-test-").toFile();Context c=new Context(root,root);IslandMemory y=new IslandMemory(c,"yue");y.note("慢一点");y.complete("奶茶","少甜嗎？","茶餐厅");y.complete("車站","直行。","问路");y.complete("少甜","要冰嗎？","茶餐厅");
  JSONArray h=y.history("要冰","茶餐厅");check(h.length()==5&&h.getJSONObject(0).getString("content").equals("奶茶")&&h.getJSONObject(3).getString("content").equals("要冰嗎？"),"scene history chronological across interleaved dialogues");check(!h.toString().contains("車站"),"other scene not injected into current history");check(y.history("你好","购物").length()==1,"new scene starts without unrelated turns");check(!y.context("奶茶","茶餐厅").contains("直行"),"retrieved contextual memory stays in scene");check(y.context("奶茶","茶餐厅").contains("慢一点"),"preferences shared across scenes");check(new IslandMemory(new Context(root,root),"yue").scenePairs("茶餐厅",1).getJSONObject(0).getString("user").equals("少甜"),"resume survives reopening");
  y.clearScene("茶餐厅");check(y.scenePairs("茶餐厅",300).length()==0&&y.history("重开","茶餐厅").length()==1,"restart removes scene context");check(y.scenePairs("问路",1).length()==1&&y.note().equals("慢一点"),"restart preserves other scenes and preference");check(y.scenePairs("问路",0).length()==0,"bounded transcript limit");
  SpeechDeadline d=new SpeechDeadline();d.system("1",100);check(!d.expired("1",4099)&&d.expired("1",4100),"missing system start times out");d.fallback("1",4100);check(!d.accepts("1",false)&&d.accepts("1",true),"late system stop/done cannot end fallback");check(d.expired("1",24100),"stalled synthesis or prepare times out");d.started("1",true,24000,12000);check(!d.expired("1",45999)&&d.expired("1",46000),"fallback playback has bounded timeout");d.clear();check(!d.accepts("1",true)&&!d.expired("1",999999),"interrupt clears all callbacks and deadlines");d.system("2",50000);d.fallback("1",60000);d.started("1",true,60000,90000);check(d.accepts("2",false)&&d.expired("2",54000),"stale turn cannot modify current deadline");d.started("2",false,51000,35000);check(!d.expired("2",95999)&&d.expired("2",96000),"started system utterance also times out");
  System.out.println("CONTINUATION_CHECKS: "+checks);
 }
}
